package tv.ezano.app

import org.json.JSONArray
import org.json.JSONObject
import java.time.*
import java.time.format.DateTimeFormatter
import java.util.UUID

enum class Kind { LIVE, MOVIE, SERIES, EPISODE }
data class Provider(val id: String = UUID.randomUUID().toString(), val name: String, val type: String = "xtream", val url: String, val user: String = "", val password: String = "", val epg: String = "", val mac: String = "", val enabled: Boolean = true)
data class Channel(val id: String, val provider: String, val sourceId: String, val name: String, val url: String, val kind: Kind = Kind.LIVE, val group: String = "General", val logo: String = "", val epgId: String = "", val description: String = "", val backdrop: String = "", val year: String = "", val rating: String = "", val catchupDays: Int = 0, val catchupSource: String = "", val catchupMode: String = "", val headers: Map<String, String> = emptyMap(), val language: String = "", val country: String = "", val certification: String = "", val genre: String = "", val popularity: Double = 0.0, val seriesId: String = "", val subtitleTracks: List<SubtitleSource> = emptyList())
data class Program(val id: String, val channelId: String, val title: String, val start: Long, val end: Long, val description: String = "")
data class Recording(val id: String = UUID.randomUUID().toString(), val channel: Channel, val title: String, val start: Long, val end: Long, val repeat: String = "once", val reminder: Boolean = false, val autoPlay: Boolean = false, val status: String = "scheduled", val path: String = "", val error: String = "")
data class Prefs(val resumeLast: Boolean = false, val afr: Boolean = true, val panelSeconds: Int = 7, val panelOpacity: Float = .90f, val guideHours: Int = 12, val retentionDays: Int = 3, val preview: Boolean = false, val reduceMotion: Boolean = false, val accent: String = "red", val pinHash: String = "", val pinSalt: String = "", val lockedSections: Set<String> = emptySet(), val pinFailures: Int = 0, val pinBlockedUntil: Long = 0, val subtitleApiKey: String = "", val subtitleLanguage: String = "en", val autoSubtitles: Boolean = true, val subtitleBackground: Boolean = false)
// revision is an in-memory snapshot token; equality never scans a replacement catalog.
data class Library(val revision: Long = 0, val providers: List<Provider> = emptyList(), val channels: List<Channel> = emptyList(), val programs: List<Program> = emptyList(), val favorites: Set<String> = emptySet(), val hidden: Set<String> = emptySet(), val hiddenGroups: Set<String> = emptySet(), val locked: Set<String> = emptySet(), val groups: Map<String, List<String>> = emptyMap(), val order: List<String> = emptyList(), val positions: Map<String, Long> = emptyMap(), val lastChannel: String = "", val recordings: List<Recording> = emptyList(), val prefs: Prefs = Prefs(), val lastGuideSync: Long = 0, val recent: List<Channel> = emptyList())

object Json {
    fun array(a: JSONArray?) = (0 until (a?.length() ?: 0)).map { a!!.get(it) }
    fun strings(a: JSONArray?) = array(a).map { it.toString() }
    fun Provider.json() = JSONObject().put("id",id).put("name",name).put("type",type).put("url",url).put("user",user).put("password",password).put("epg",epg).put("mac",mac).put("enabled",enabled)
    fun provider(o: JSONObject) = Provider(o.getString("id"),o.getString("name"),o.optString("type","xtream"),o.getString("url"),o.optString("user"),o.optString("password"),o.optString("epg"),o.optString("mac"),o.optBoolean("enabled",true))
    fun Channel.json() = JSONObject().put("id",id).put("provider",provider).put("sourceId",sourceId).put("name",name).put("url",url).put("kind",kind.name).put("group",group).put("logo",logo).put("epgId",epgId).put("description",description).put("backdrop",backdrop).put("year",year).put("rating",rating).put("catchupDays",catchupDays).put("catchupSource",catchupSource).put("catchupMode",catchupMode).put("headers",JSONObject(headers)).put("language",language).put("country",country).put("certification",certification).put("genre",genre).put("popularity",popularity).put("seriesId",seriesId).put("subtitleTracks",JSONArray(subtitleTracks.map {JSONObject().put("url",it.url).put("label",it.label).put("language",it.language).put("mime",it.mime)}))
    fun channel(o: JSONObject) = Channel(o.getString("id"),o.getString("provider"),o.optString("sourceId"),o.getString("name"),o.getString("url"),Kind.valueOf(o.optString("kind","LIVE")),o.optString("group","General"),o.optString("logo"),o.optString("epgId"),o.optString("description"),o.optString("backdrop"),o.optString("year"),o.optString("rating"),o.optInt("catchupDays"),o.optString("catchupSource"),o.optString("catchupMode"),o.optJSONObject("headers")?.let { h -> h.keys().asSequence().associateWith { h.getString(it) } } ?: emptyMap(),o.optString("language"),o.optString("country"),o.optString("certification"),o.optString("genre"),o.optDouble("popularity",0.0).takeIf {it.isFinite()}?:0.0,o.optString("seriesId"),array(o.optJSONArray("subtitleTracks")).mapNotNull {value->(value as? JSONObject)?.let {SubtitleSource(it.optString("url"),it.optString("label"),it.optString("language","en"),it.optString("mime","text/vtt"))}})
    fun Program.json() = JSONObject().put("id",id).put("channelId",channelId).put("title",title).put("start",start).put("end",end).put("description",description)
    fun program(o: JSONObject) = Program(o.getString("id"),o.getString("channelId"),o.getString("title"),o.getLong("start"),o.getLong("end"),o.optString("description"))
    fun Recording.json() = JSONObject().put("id",id).put("channel",channel.json()).put("title",title).put("start",start).put("end",end).put("repeat",repeat).put("reminder",reminder).put("autoPlay",autoPlay).put("status",status).put("path",path).put("error",error)
    fun recording(o: JSONObject) = Recording(o.getString("id"),channel(o.getJSONObject("channel")),o.getString("title"),o.getLong("start"),o.getLong("end"),o.optString("repeat","once"),o.optBoolean("reminder"),o.optBoolean("autoPlay"),o.optString("status","scheduled"),o.optString("path"),o.optString("error"))
    fun encode(s: Library): String = JSONObject().apply {
        put("version",1); put("providers",JSONArray(s.providers.map { it.json() })); put("channels",JSONArray(s.channels.map { it.json() })); put("programs",JSONArray(s.programs.map { it.json() })); put("favorites",JSONArray(s.favorites)); put("hidden",JSONArray(s.hidden)); put("hiddenGroups",JSONArray(s.hiddenGroups)); put("locked",JSONArray(s.locked)); put("groups",JSONObject().apply { s.groups.forEach { (k,v)->put(k,JSONArray(v)) } }); put("order",JSONArray(s.order)); put("positions",JSONObject(s.positions)); put("lastChannel",s.lastChannel); put("recordings",JSONArray(s.recordings.map { it.json() })); put("lastGuideSync",s.lastGuideSync); put("recent",JSONArray(s.recent.take(30).map {it.json()}))
        put("prefs",JSONObject().apply { val p=s.prefs; put("resumeLast",p.resumeLast); put("afr",p.afr); put("panelSeconds",p.panelSeconds); put("panelOpacity",p.panelOpacity); put("guideHours",p.guideHours); put("retentionDays",p.retentionDays); put("preview",p.preview); put("reduceMotion",p.reduceMotion); put("accent",p.accent); put("pinHash",p.pinHash); put("pinSalt",p.pinSalt); put("lockedSections",JSONArray(p.lockedSections)); put("pinFailures",p.pinFailures); put("pinBlockedUntil",p.pinBlockedUntil); put("subtitleApiKey",p.subtitleApiKey); put("subtitleLanguage",p.subtitleLanguage); put("autoSubtitles",p.autoSubtitles); put("subtitleBackground",p.subtitleBackground) })
    }.toString()
    fun decode(raw: String): Library { val o=JSONObject(raw); require(o.optInt("version")==1) { "Unsupported backup version" }; val p=o.optJSONObject("prefs")?:JSONObject()
        return Library(0,array(o.optJSONArray("providers")).map { provider(it as JSONObject) },array(o.optJSONArray("channels")).map { channel(it as JSONObject) },array(o.optJSONArray("programs")).map { program(it as JSONObject) },strings(o.optJSONArray("favorites")).toSet(),strings(o.optJSONArray("hidden")).toSet(),strings(o.optJSONArray("hiddenGroups")).toSet(),strings(o.optJSONArray("locked")).toSet(),o.optJSONObject("groups")?.let { g-> g.keys().asSequence().associateWith { strings(g.optJSONArray(it)) } }?:emptyMap(),strings(o.optJSONArray("order")),o.optJSONObject("positions")?.let { g->g.keys().asSequence().associateWith { g.getLong(it) } }?:emptyMap(),o.optString("lastChannel"),array(o.optJSONArray("recordings")).map { recording(it as JSONObject) },Prefs(p.optBoolean("resumeLast"),p.optBoolean("afr",true),p.optInt("panelSeconds",7).coerceIn(3,30),p.optDouble("panelOpacity",.9).toFloat().coerceIn(.3f,1f),p.optInt("guideHours",12).coerceIn(1,48),p.optInt("retentionDays",3).coerceIn(0,14),p.optBoolean("preview"),p.optBoolean("reduceMotion"),p.optString("accent","red"),p.optString("pinHash"),p.optString("pinSalt"),strings(p.optJSONArray("lockedSections")).toSet(),p.optInt("pinFailures"),p.optLong("pinBlockedUntil"),p.optString("subtitleApiKey"),p.optString("subtitleLanguage","en"),p.optBoolean("autoSubtitles",true),p.optBoolean("subtitleBackground",false)),o.optLong("lastGuideSync"),array(o.optJSONArray("recent")).take(30).mapNotNull {it as? JSONObject}.map(::channel))
    }
}
fun nextOccurrence(r: Recording, now: Long = System.currentTimeMillis()): Recording? {
    if(r.repeat=="once") return null
    var next=Instant.ofEpochMilli(r.start).atZone(ZoneId.systemDefault())
    do { next=if(r.repeat=="daily") next.plusDays(1) else next.plusWeeks(1) } while(next.toInstant().toEpochMilli()<=now)
    val start=next.toInstant().toEpochMilli()
    return r.copy(id=UUID.randomUUID().toString(),start=start,end=start+(r.end-r.start),status="scheduled",path="",error="")
}
fun timeLabel(ms: Long) = Instant.ofEpochMilli(ms).atZone(ZoneId.systemDefault()).format(DateTimeFormatter.ofPattern("h:mm a"))
